import 'dart:convert';

/// Bundled summary of species-level taxonomy changes per MDD release,
/// generated by `tools/release_changes.py`.
const releaseChangesAsset = 'assets/data/release_changes.json';

/// Species-level taxonomy changes from [prevVersion] to [version].
class ReleaseChange {
  const ReleaseChange({
    required this.version,
    required this.prevVersion,
    this.releaseDate,
    this.deNovo = 0,
    this.split = 0,
    this.lump = 0,
    this.added = 0,
    this.removed = 0,
  });

  final String version;
  final String prevVersion;
  final DateTime? releaseDate;
  final int deNovo;
  final int split;
  final int lump;

  /// Other additions, such as de-extinctions.
  final int added;

  /// Species removed without being lumped.
  final int removed;

  int get gained => deNovo + split + added;
  int get lost => lump + removed;
  int get net => gained - lost;

  factory ReleaseChange.fromJson(Map<String, dynamic> json) => ReleaseChange(
    version: json['version'] as String,
    prevVersion: json['prevVersion'] as String,
    releaseDate: DateTime.tryParse(json['releaseDate'] as String? ?? ''),
    deNovo: json['deNovo'] as int? ?? 0,
    split: json['split'] as int? ?? 0,
    lump: json['lump'] as int? ?? 0,
    added: json['added'] as int? ?? 0,
    removed: json['removed'] as int? ?? 0,
  );
}

/// Parses the bundled summary, newest release first.
List<ReleaseChange> parseReleaseChanges(String source) {
  final releases = [
    for (final json in jsonDecode(source) as List<dynamic>)
      ReleaseChange.fromJson(json as Map<String, dynamic>),
  ];
  releases.sort((a, b) => _compareVersions(b.version, a.version));
  return releases;
}

int _compareVersions(String a, String b) {
  final left = a.split('.').map(int.tryParse).toList();
  final right = b.split('.').map(int.tryParse).toList();
  for (var i = 0; i < left.length && i < right.length; i++) {
    final diff = (left[i] ?? 0) - (right[i] ?? 0);
    if (diff != 0) return diff;
  }
  return left.length - right.length;
}

/// A signed count such as "+33" or "−6".
String formatSignedCount(int value) {
  if (value > 0) return '+$value';
  if (value < 0) return '−${-value}';
  return '0';
}
